B.arc=new A.nv("Upgrader \u2014 \u0441\u0438\u043c\u0443\u043b\u044f\u0442\u043e\u0440. \u0411\u0430\u043b\u0430\u043d\u0441 \u0438 \u043f\u0440\u0435\u0434\u043c\u0435\u0442\u044b \u0432\u044b\u043c\u044b\u0448\u043b\u0435\u043d\u043d\u044b\u0435. \u0420\u0435\u0430\u043b\u044c\u043d\u044b\u0435 \u0434\u0435\u043d\u044c\u0433\u0438 \u043d\u0435 \u043f\u0440\u0438\u043d\u0438\u043c\u0430\u044e\u0442\u0441\u044f, \u043d\u0435 \u0432\u044b\u043f\u043b\u0430\u0447\u0438\u0432\u0430\u044e\u0442\u0441\u044f \u0438 \u043d\u0435 \u0432\u044b\u0438\u0433\u0440\u044b\u0432\u0430\u044e\u0442\u0441\u044f. \u041f\u0440\u0435\u0434\u043c\u0435\u0442\u044b \u043d\u0435\u043b\u044c\u0437\u044f \u043a\u0443\u043f\u0438\u0442\u044c \u0437\u0430 \u0434\u0435\u043d\u044c\u0433\u0438, \u043f\u0440\u043e\u0434\u0430\u0442\u044c, \u043e\u0431\u043c\u0435\u043d\u044f\u0442\u044c, \u0432\u044b\u0432\u0435\u0441\u0442\u0438 \u0432 Steam \u0438\u043b\u0438 \u0432 \u043b\u044e\u0431\u0443\u044e \u0438\u0433\u0440\u0443 Valve.",null)
B.aqX=new A.ns("\u041f\u0440\u0430\u0432\u0430 \u043d\u0430 \u043f\u0440\u0435\u0434\u043c\u0435\u0442\u044b",null)
B.arh=new A.nv("\u041f\u0440\u0438\u043b\u043e\u0436\u0435\u043d\u0438\u0435 \u0441\u043e\u0437\u0434\u0430\u043d\u043e \u043d\u0435\u0437\u0430\u0432\u0438\u0441\u0438\u043c\u043e \u0438 \u043d\u0435 \u0441\u0432\u044f\u0437\u0430\u043d\u043e \u0441 Valve Corporation, \u043d\u0435 \u043e\u0434\u043e\u0431\u0440\u0435\u043d\u043e \u0438 \u043d\u0435 \u0441\u043f\u043e\u043d\u0441\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u0435\u044e.\n\nCounter-Strike, CS2, \u043d\u0430\u0437\u0432\u0430\u043d\u0438\u044f \u0438 \u0438\u0437\u043e\u0431\u0440\u0430\u0436\u0435\u043d\u0438\u044f \u043f\u0440\u0435\u0434\u043c\u0435\u0442\u043e\u0432 \u2014 \u0442\u043e\u0432\u0430\u0440\u043d\u044b\u0435 \u0437\u043d\u0430\u043a\u0438 \u0438 \u0441\u043e\u0431\u0441\u0442\u0432\u0435\u043d\u043d\u043e\u0441\u0442\u044c Valve Corporation. \u041e\u043d\u0438 \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u0443\u044e\u0442\u0441\u044f \u0438\u0441\u043a\u043b\u044e\u0447\u0438\u0442\u0435\u043b\u044c\u043d\u043e \u0434\u043b\u044f \u043e\u043f\u0438\u0441\u0430\u043d\u0438\u044f \u043f\u0440\u0435\u0434\u043c\u0435\u0442\u043e\u0432 \u0432\u043d\u0443\u0442\u0440\u0438 \u0438\u0433\u0440\u043e\u0432\u043e\u0433\u043e \u0441\u0438\u043c\u0443\u043b\u044f\u0442\u043e\u0440\u0430.\n\n\u0426\u0435\u043d\u044b \u0441\u043f\u0440\u0430\u0432\u043e\u0447\u043d\u044b\u0435, \u0431\u0435\u0440\u0443\u0442\u0441\u044f \u0438\u0437 \u043e\u0442\u043a\u0440\u044b\u0442\u044b\u0445 \u0434\u0430\u043d\u043d\u044b\u0445 Steam Community Market \u0438 \u043d\u0435 \u044f\u0432\u043b\u044f\u044e\u0442\u0441\u044f \u043e\u0444\u0435\u0440\u0442\u043e\u0439.",null)
B.ar_=new A.ns("\u0414\u0430\u043d\u043d\u044b\u0435",null)
B.ard=new A.nv("\u0411\u0435\u0437 \u0432\u0445\u043e\u0434\u0430 \u0432 \u0430\u043a\u043a\u0430\u0443\u043d\u0442 \u0438\u0433\u0440\u043e\u0432\u044b\u0435 \u0434\u0430\u043d\u043d\u044b\u0435 \u043d\u0435 \u0441\u043e\u0431\u0438\u0440\u0430\u044e\u0442\u0441\u044f: \u043f\u0440\u043e\u0433\u0440\u0435\u0441\u0441 \u043b\u0435\u0436\u0438\u0442 \u0442\u043e\u043b\u044c\u043a\u043e \u043d\u0430 \u0432\u0430\u0448\u0435\u043c \u0443\u0441\u0442\u0440\u043e\u0439\u0441\u0442\u0432\u0435. \u041d\u0430\u0440\u0443\u0436\u0443 \u0443\u0445\u043e\u0434\u0438\u0442 \u043e\u0434\u0438\u043d \u043e\u0431\u0435\u0437\u043b\u0438\u0447\u0435\u043d\u043d\u044b\u0439 \u0441\u0438\u0433\u043d\u0430\u043b \u0440\u0430\u0437 \u0432 \u0434\u0432\u0435 \u043c\u0438\u043d\u0443\u0442\u044b \u2014 \u0441\u043b\u0443\u0447\u0430\u0439\u043d\u043e\u0435 \u0447\u0438\u0441\u043b\u043e, \u043f\u0440\u0438\u0434\u0443\u043c\u0430\u043d\u043d\u043e\u0435 \u043f\u0440\u0438 \u0437\u0430\u043f\u0443\u0441\u043a\u0435: \u043f\u043e \u043d\u0435\u043c\u0443 \u043c\u044b \u0441\u0447\u0438\u0442\u0430\u0435\u043c, \u0441\u043a\u043e\u043b\u044c\u043a\u043e \u043a\u043e\u043f\u0438\u0439 \u0438\u0433\u0440\u044b \u043e\u0442\u043a\u0440\u044b\u0442\u043e \u043e\u0434\u043d\u043e\u0432\u0440\u0435\u043c\u0435\u043d\u043d\u043e. \u041e\u043d\u043e \u0436\u0438\u0432\u0451\u0442 \u0432 \u043f\u0430\u043c\u044f\u0442\u0438 \u043f\u0440\u0438\u043b\u043e\u0436\u0435\u043d\u0438\u044f, \u0438\u0441\u0447\u0435\u0437\u0430\u0435\u0442 \u0432\u043c\u0435\u0441\u0442\u0435 \u0441 \u043d\u0438\u043c \u0438 \u043d\u0435 \u0441\u0432\u044f\u0437\u0430\u043d\u043e \u043d\u0438 \u0441 \u0432\u0430\u043c\u0438, \u043d\u0438 \u0441 \u0443\u0441\u0442\u0440\u043e\u0439\u0441\u0442\u0432\u043e\u043c.\n\n\u041f\u043e\u0441\u043b\u0435 \u0432\u0445\u043e\u0434\u0430 \u0447\u0435\u0440\u0435\u0437 Google \u0441\u043e\u0445\u0440\u0430\u043d\u044f\u044e\u0442\u0441\u044f \u0438\u0434\u0435\u043d\u0442\u0438\u0444\u0438\u043a\u0430\u0442\u043e\u0440 \u0430\u043a\u043a\u0430\u0443\u043d\u0442\u0430, \u043f\u043e\u0447\u0442\u0430, \u0438\u043c\u044f \u0438 \u0444\u043e\u0442\u043e \u043f\u0440\u043e\u0444\u0438\u043b\u044f, \u0430 \u0442\u0430\u043a\u0436\u0435 \u0438\u0433\u0440\u043e\u0432\u043e\u0439 \u043f\u0440\u043e\u0433\u0440\u0435\u0441\u0441 \u2014 \u0447\u0442\u043e\u0431\u044b \u043f\u0435\u0440\u0435\u043d\u043e\u0441\u0438\u0442\u044c \u0435\u0433\u043e \u043c\u0435\u0436\u0434\u0443 \u0443\u0441\u0442\u0440\u043e\u0439\u0441\u0442\u0432\u0430\u043c\u0438. \u041f\u0430\u0440\u043e\u043b\u044c \u043e\u0442 \u0430\u043a\u043a\u0430\u0443\u043d\u0442\u0430 \u043f\u0440\u0438\u043b\u043e\u0436\u0435\u043d\u0438\u044e \u043d\u0435 \u043f\u0435\u0440\u0435\u0434\u0430\u0451\u0442\u0441\u044f.\n\n\u041e\u043d\u043b\u0430\u0439\u043d-\u0440\u0435\u0436\u0438\u043c \u0440\u0430\u0431\u043e\u0442\u0430\u0435\u0442 \u043d\u0430 \u043d\u0430\u0448\u0435\u043c \u0441\u0435\u0440\u0432\u0435\u0440\u0435. \u0422\u0430\u043c \u0445\u0440\u0430\u043d\u044f\u0442\u0441\u044f \u043d\u0438\u043a, \u0431\u0430\u043b\u0430\u043d\u0441, \u043f\u0440\u0435\u0434\u043c\u0435\u0442\u044b, \u0438\u0441\u0442\u043e\u0440\u0438\u044f \u0434\u0443\u044d\u043b\u0435\u0439 \u0438 \u0441\u043f\u0438\u0441\u043e\u043a \u0434\u0440\u0443\u0437\u0435\u0439. \u041f\u043e\u0447\u0442\u044b, \u0438\u043c\u0435\u043d\u0438 \u0438 \u0444\u043e\u0442\u043e \u043f\u0440\u043e\u0444\u0438\u043b\u044f \u043d\u0430 \u043d\u0451\u043c \u043d\u0435\u0442.\n\n\u0414\u0440\u0443\u0433\u0438\u043c \u0438\u0433\u0440\u043e\u043a\u0430\u043c \u0432\u0438\u0434\u0435\u043d \u0442\u043e\u043b\u044c\u043a\u043e \u0432\u0430\u0448 \u043d\u0438\u043a \u2014 \u043d\u0438 \u0431\u0430\u043b\u0430\u043d\u0441\u0430, \u043d\u0438 \u0438\u043d\u0432\u0435\u043d\u0442\u0430\u0440\u044f, \u043d\u0438 \u043f\u043e\u0447\u0442\u044b \u043e\u043d\u0438 \u043d\u0435 \u0432\u0438\u0434\u044f\u0442.",null)
